import type { AddressAction, PanelChromeState } from "./panelChrome.js";
import { desktopNeutralShortcutLabel } from "./desktopKeymap.js";

export type AddressNavigationMode = "current" | "child" | "root" | "external";

export const BROWSER_NAVIGATION_TRANSITIONS = [
  "link",
  "typed",
  "generated",
  "keyword_generated",
  "reload",
  "back_forward",
] as const;

export type BrowserNavigationTransition = (typeof BROWSER_NAVIGATION_TRANSITIONS)[number];

export interface BrowserNavigationIntent {
  transition?: BrowserNavigationTransition;
  typed?: boolean;
}

export interface AddressNavigationModifiers {
  shiftKey?: boolean;
  metaKey?: boolean;
  ctrlKey?: boolean;
  altKey?: boolean;
}

/**
 * Browser-familiar application accelerators for panel lifecycle.
 *
 * @deprecated Read the binding from `desktopKeymap`, which is what the menu
 * registers. These literals are kept only for callers not yet converted.
 */
export const PANEL_KEYBOARD_ACCELERATORS = {
  newPanel: "CmdOrCtrl+T",
  closePanel: "CmdOrCtrl+W",
} as const;

/** Mouse button 1 is the browser-standard auxiliary action for closing a tab-like item. */
export function isPanelClosePointerButton(button: number): boolean {
  return button === 1;
}

export type PanelCommandId =
  | "back"
  | "command-agent"
  | "forward"
  | "reload-panel"
  | "reload-view"
  | "force-reload-view"
  | "rebuild-panel"
  | "stop"
  | "focus-address"
  | "copy-address"
  | "share-address"
  | "copy-panel-id"
  | "open-external"
  | "duplicate"
  | "open-child-beside"
  | "add-child"
  | "add-child-below"
  | "open-in-new-column"
  | "close-pane"
  | "toggle-pin"
  | "unload"
  | "archive";

/** Canonical desktop tree/breadcrumb context-menu grouping. */
export const PANEL_CONTEXT_MENU_SECTIONS = [
  ["back", "forward", "stop"],
  ["reload-panel"],
  // Offered per panel because the overlay binds to the panel the user pointed
  // at, not to whatever happens to be focused — and because that binding decides
  // which conversation Ctrl+K would resume.
  ["command-agent"],
  ["open-child-beside", "add-child", "add-child-below", "open-in-new-column", "duplicate"],
  ["copy-address", "open-external", "copy-panel-id"],
  ["toggle-pin", "close-pane", "archive"],
] as const satisfies ReadonlyArray<ReadonlyArray<PanelCommandId>>;

export interface PanelCommandContext {
  chrome?: PanelChromeState | null;
  addressBarVisible?: boolean;
  /** Client-local pin state of the panel the command targets. */
  isPinned?: boolean;
  /** Number of direct children available for one-click child presentation. */
  childCount?: number;
  /** Per-device presentation state; absent when the panel is not in a pane. */
  presentation?: {
    kind: "solo" | "stacked";
    canSplitBelow: boolean;
  };
}

export interface PanelCommandDefinition {
  id: PanelCommandId;
  label: string;
  /** Canonical, renderer-neutral explanation shown by discoverability surfaces. */
  description: string;
  shortcut?: string;
  visible: boolean;
  enabled: boolean;
}

import { DEFAULT_SEARCH_TEMPLATE, webSearchUrl } from "./webSearch.js";
export { DEFAULT_SEARCH_TEMPLATE } from "./webSearch.js";

export function applySearchTemplate(
  query: string,
  template: string = DEFAULT_SEARCH_TEMPLATE
): string {
  const encoded = encodeURIComponent(query);
  if (/%s|\{searchTerms\}/.test(template)) return webSearchUrl(template, query);
  const separator = template.includes("?") ? "&" : "?";
  return `${template}${separator}q=${encoded}`;
}

export function canonicalizeBrowserHistoryUrl(url: string): string | null {
  try {
    const parsed = new URL(url);
    if (parsed.protocol !== "http:" && parsed.protocol !== "https:") return null;
    parsed.protocol = parsed.protocol.toLowerCase();
    parsed.hostname = parsed.hostname.toLowerCase();
    parsed.hash = "";
    if (
      (parsed.protocol === "http:" && parsed.port === "80") ||
      (parsed.protocol === "https:" && parsed.port === "443")
    ) {
      parsed.port = "";
    }
    return parsed.toString();
  } catch {
    return null;
  }
}

export function getBrowserNavigationIntentForCommand(
  command: PanelCommandId
): BrowserNavigationIntent | null {
  if (command === "back" || command === "forward")
    return { transition: "back_forward", typed: false };
  if (command === "reload-panel" || command === "reload-view" || command === "force-reload-view") {
    return { transition: "reload", typed: false };
  }
  return null;
}

export function getBrowserNavigationIntentForAddressAction(
  action: AddressAction
): BrowserNavigationIntent | null {
  if (action.type === "navigate-url" && action.recordAsTyped)
    return { transition: "typed", typed: true };
  if (action.type === "search")
    return { transition: "generated", typed: Boolean(action.recordAsTyped) };
  if (action.type === "keyword-search")
    return { transition: "keyword_generated", typed: Boolean(action.recordAsTyped) };
  return null;
}

export function getAddressNavigationModeFromModifiers(
  modifiers: AddressNavigationModifiers
): AddressNavigationMode {
  if (modifiers.altKey) return "external";
  if (modifiers.metaKey || modifiers.ctrlKey) return "root";
  if (modifiers.shiftKey) return "child";
  return "current";
}

export function getPanelCommandDefinitions(
  context: PanelCommandContext = {}
): PanelCommandDefinition[] {
  const chrome = context.chrome ?? null;
  const isBrowser = chrome?.kind === "browser";
  const isPanel = chrome?.kind === "panel";
  const hasAddress = Boolean(chrome?.editableAddress || chrome?.resolvedUrl);

  return [
    {
      id: "back",
      label: "Back",
      description: "Go back in this panel's history",
      shortcut: desktopNeutralShortcutLabel("back"),
      visible: true,
      enabled: Boolean(chrome?.canGoBack),
    },
    {
      id: "forward",
      label: "Forward",
      description: "Go forward in this panel's history",
      shortcut: desktopNeutralShortcutLabel("forward"),
      visible: true,
      enabled: Boolean(chrome?.canGoForward),
    },
    {
      id: "reload-panel",
      label: "Reload",
      description: "Reload the panel",
      shortcut: desktopNeutralShortcutLabel("reload"),
      visible: true,
      enabled: Boolean(chrome),
    },
    {
      id: "reload-view",
      label: "Reload View",
      description: "Reload the current view",
      visible: true,
      enabled: Boolean(chrome),
    },
    {
      id: "force-reload-view",
      label: "Force Reload View",
      description: "Reload the view, bypassing caches",
      shortcut: desktopNeutralShortcutLabel("forceReload"),
      visible: true,
      enabled: Boolean(chrome),
    },
    {
      id: "rebuild-panel",
      label: "Rebuild Panel",
      description: "Rebuild the panel from source",
      visible: isPanel,
      enabled: isPanel,
    },
    {
      id: "stop",
      label: "Stop Loading",
      description: "Stop loading the current page",
      shortcut: desktopNeutralShortcutLabel("stop"),
      visible: true,
      enabled: Boolean(chrome?.isLoading),
    },
    {
      id: "focus-address",
      label: context.addressBarVisible ? "Focus Address" : "Show Address Bar",
      description: "Edit this panel's address",
      shortcut: desktopNeutralShortcutLabel("focusAddress"),
      visible: true,
      enabled: true,
    },
    {
      id: "copy-address",
      label: "Copy Address",
      description: "Copy this panel's address",
      visible: true,
      enabled: hasAddress,
    },
    {
      id: "share-address",
      label: "Share",
      description: "Share this panel using another app",
      visible: true,
      enabled: hasAddress,
    },
    {
      id: "copy-panel-id",
      label: "Copy Panel ID",
      description: "Copy this panel's durable identifier",
      visible: true,
      enabled: true,
    },
    {
      id: "open-external",
      label: "Open in System Browser",
      description: "Open this page in the system browser",
      visible: isBrowser,
      enabled: Boolean(chrome?.resolvedUrl && /^https?:\/\//i.test(chrome.resolvedUrl)),
    },
    {
      id: "duplicate",
      label: "Duplicate",
      description: "Open another copy as a new root panel",
      visible: true,
      enabled: Boolean(chrome),
    },
    {
      id: "open-child-beside",
      label: "Open Child Panel Beside",
      description: "Show an existing child beside this panel",
      visible: (context.childCount ?? 0) > 0,
      enabled: (context.childCount ?? 0) > 0,
    },
    {
      id: "add-child",
      label: "Create New Child Panel Beside",
      description: "Create and show a child beside this panel",
      visible: true,
      enabled: Boolean(chrome),
    },
    {
      id: "add-child-below",
      label: "Create New Child Panel Below",
      description: "Create a child below this panel",
      visible: Boolean(context.presentation?.canSplitBelow),
      enabled: Boolean(chrome && context.presentation?.canSplitBelow),
    },
    {
      id: "open-in-new-column",
      label:
        context.presentation?.kind === "stacked" ? "Move Pane to New Column" : "Open in New Column",
      description: "Give this panel its own column",
      visible: context.presentation?.kind !== "solo",
      enabled: Boolean(chrome),
    },
    {
      id: "close-pane",
      label: "Close Pane",
      description: "Close this local view without archiving the panel",
      visible: Boolean(context.presentation),
      enabled: Boolean(context.presentation),
    },
    {
      id: "toggle-pin",
      label: context.isPinned ? "Unpin Panel" : "Pin Panel",
      description: "Pinned panels stay loaded in the background",
      visible: true,
      // Pinnable even when unloaded: callers build `chrome` from the registry
      // entry, so this stays enabled for panels that only exist in the tree.
      enabled: Boolean(chrome),
    },
    {
      id: "unload",
      label: "Unload",
      description: "Free memory; reload next time the panel opens",
      visible: true,
      enabled: Boolean(chrome),
    },
    {
      id: "command-agent",
      label: "Command…",
      description:
        "Open the command palette over this panel, resuming its Quickfire agent conversation if it has one",
      shortcut: desktopNeutralShortcutLabel("commandPalette"),
      visible: true,
      enabled: Boolean(chrome),
    },
    {
      id: "archive",
      label: "Archive Panel",
      description: "Remove this panel and its descendants from the active tree",
      shortcut: desktopNeutralShortcutLabel("closePanel"),
      visible: true,
      enabled: Boolean(chrome),
    },
  ];
}

export function getAvailablePanelCommands(
  context: PanelCommandContext = {},
  ids?: readonly PanelCommandId[]
): PanelCommandDefinition[] {
  const allowed = ids ? new Set<PanelCommandId>(ids) : null;
  return getPanelCommandDefinitions(context).filter((command) => {
    if (!command.visible || !command.enabled) return false;
    return !allowed || allowed.has(command.id);
  });
}
